/* adelefeld/dump.h: the dump form (version 1, field Q) for adf_rat, adf_fball, adf_scaled,
   adf_adele, adf_cadele: loaders with context bindings, dumpers, inspection of context occurrences.

   Contract: docs/conventions.md 0.4, section 10 (grammar 10.1; rules 10.2: strict loader CV-38,
   real balls as arb_dump_str writes them, validation of the whole text before any FLINT load
   function CV-52, context bindings of gate finding G3, descriptors and inspection of closure
   finding C2), 8.1 (interface), 8.4, 8.5 (limits, order of checks), 4.3, 12.8; docs/SPEC.md 10
   item 2 (M0-D9). Golden vectors: tests/golden/dump.tsv (conventions 11.3 item 5). Reference:
   proto/text_grammar.py. Implemented in work package 1.4 (docs/PLAN.md section 6).

   The five bodies used here (conventions 10.1): "rat", "fball" (form "g" global: A H d; form "l"
   local: d, context, residues), "scaled" (form "x" exact: num den; form "s": num(s) den(s) u; then
   the context), "adele" (archimedean count 1, one arb, one fball), "cadele" (count 1, one acb, one
   fball). Every dump starts "adf1 Q ".

   Rules common to the loaders (conventions 10.2, 8.5, 4.3):
   - Input (s, len) as for the value form (adelefeld/text.h); lim = NULL means the defaults.
   - Strict: only canonical text is accepted; the fields must satisfy the predicates of conventions
     section 5 (for a local fball the raw predicate L, CV-55). The loader never canonicalises.
   - The whole text is validated before any FLINT load function sees any of it (CV-52, D9); an arb
     field is accepted only if both mantissas are odd or the pair is "0 0", and the radius mantissa
     is positive and below 2^30 (mag.h:117); anything else is ADF_DOMAIN.
   - Statuses: ADF_OK, ADF_PARSE, ADF_LIMIT, ADF_UNSUPPORTED (a version other than 1, a field other
     than Q), ADF_DOMAIN (conventions 3.2 row "Loaders of the dump form"; order of 8.5). On every
     status other than ADF_OK the output value is untouched.
   - Every function that validates a dump validates every body of conventions 10.1, also the
     bodies without a loader here. For the body "qclass" of the form "pieces" the binary exponents
     of the real ball of every piece are limited (decision M1-D9, conventions 8.4): an exponent of
     the midpoint or of the radius above ADF_DUMP_QCLASS_EXP_MAX in absolute value is ADF_LIMIT,
     at stage 4 of conventions 8.5, decided on the digit strings. The form "lift" and the other
     bodies have no such limit. A context occurrence of more than ADF_MODCTX_MAX_BLOCKS blocks is
     ADF_UNSUPPORTED at stage 5 (decision M1-D5, adelefeld/modctx.h).
   - Context bindings (conventions 10.2, G3): there is one context occurrence per local fball and
     per scaled value, in dump traversal order. binds[i] is the caller-owned context for occurrence
     i; it must match that occurrence's modulus and ordered blocks (adf_modctx_matches_desc);
     repeated occurrences may share a pointer. A binding count other than the number of
     occurrences, a NULL binding, or a binding that does not match is ADF_DOMAIN. The loaded value
     borrows the bound contexts; value fields and backend are restored exactly relative to them.
     Loading and then adf_x_identical with the original value requires binding each occurrence to
     its original context pointer.
   - adf_x_load_str(x, s, len, ctx, lim) is the one-context convenience: it stands for binds with
     ctx at every occurrence; for a dump without occurrences any ctx, NULL included, is accepted.

   Rules common to the dumpers (conventions 8.1, 10.2): the text of conventions 10.1 for the stored
   data (raw local data, context K, k, q_1..q_k); allocated with flint_malloc, byte length in *len,
   NUL at s[len], freed with adf_str_free; never fails. Loading the text with the value's own
   contexts gives an identical value, and dumping it again gives the same bytes (CV-38).

   Rules common to the inspectors adf_x_dump_inspect(nctx, descs, s, len, lim) (conventions 10.2,
   closure finding C2, verbatim): "With descs=NULL, ignore the incoming *nctx and write the
   occurrence count only on OK. Otherwise incoming *nctx is capacity in initialized descriptors.
   Validate the whole dump first; insufficient capacity returns ADF_LIMIT with *nctx and every
   descriptor untouched. On OK replace the first required descriptors, releasing their old contents,
   write that count to *nctx, and leave the rest untouched. Other failures also leave all outputs
   untouched. Statuses are loader statuses." No value and no context is constructed. */

#ifndef ADELEFELD_DUMP_H
#define ADELEFELD_DUMP_H

#include "adelefeld/common.h"
#include "adelefeld/status.h"
#include "adelefeld/rat.h"
#include "adelefeld/fball.h"
#include "adelefeld/adele.h"
#include "adelefeld/text.h"
#include "adelefeld/modctx.h"
#include "adelefeld/scaled.h"

/* The largest absolute binary exponent of the midpoint and of the radius of the real ball of a
   piece of a dumped qclass, form "pieces" (decision M1-D9): 2^20, the bound of ADF_RECON_EXP_MAX
   (decision M1-D3). It is not a field of adf_text_limits_t: a caller cannot change it. */
#define ADF_DUMP_QCLASS_EXP_MAX 1048576

#ifdef __cplusplus
extern "C" {
#endif

/* The binding array is declared `const adf_modctx_struct * const * binds`: the loader reads the
   array and never writes it (conventions 10.2 writes `const adf_modctx_struct ** binds`; the added
   const lets C callers pass an array of const pointers without a cast). nbinds is a size_t
   (conventions 12.10, closure C2). */

/* ---- adf_rat: body "rat num den" (no context occurrence) ---- */
int adf_rat_load_str(adf_rat_t x, const char * s, size_t len, const adf_modctx_struct * ctx,
                     const adf_text_limits_t * lim);
int adf_rat_load_str_binds(adf_rat_t x, const char * s, size_t len,
                           const adf_modctx_struct * const * binds, size_t nbinds,
                           const adf_text_limits_t * lim);
char * adf_rat_dump_str(size_t * len, const adf_rat_t x);
int adf_rat_dump_inspect(size_t * nctx, adf_ctx_desc_t * descs, const char * s, size_t len,
                         const adf_text_limits_t * lim);

/* ---- adf_fball: body "fball g A H d" or "fball l d K k q_1..q_k r_1..r_k" (0 or 1 occurrence) ---- */
int adf_fball_load_str(adf_fball_t x, const char * s, size_t len, const adf_modctx_struct * ctx,
                       const adf_text_limits_t * lim);
int adf_fball_load_str_binds(adf_fball_t x, const char * s, size_t len,
                             const adf_modctx_struct * const * binds, size_t nbinds,
                             const adf_text_limits_t * lim);
char * adf_fball_dump_str(size_t * len, const adf_fball_t x);
int adf_fball_dump_inspect(size_t * nctx, adf_ctx_desc_t * descs, const char * s, size_t len,
                           const adf_text_limits_t * lim);

/* ---- adf_scaled: body "scaled x num den ctx" or "scaled s num den u ctx" (1 occurrence).
   The value form does not record the policy; a scaled value is read from the value form by reading
   an adf_fball and converting it (conventions 9.4), so this is the only text reader of the type. ---- */
int adf_scaled_load_str(adf_scaled_t x, const char * s, size_t len, const adf_modctx_struct * ctx,
                        const adf_text_limits_t * lim);
int adf_scaled_load_str_binds(adf_scaled_t x, const char * s, size_t len,
                              const adf_modctx_struct * const * binds, size_t nbinds,
                              const adf_text_limits_t * lim);
char * adf_scaled_dump_str(size_t * len, const adf_scaled_t x);
int adf_scaled_dump_inspect(size_t * nctx, adf_ctx_desc_t * descs, const char * s, size_t len,
                            const adf_text_limits_t * lim);

/* adf_scaled_get_str(len, x): the value form of the finite ball that x denotes: "(* ; F)" with centre
   s u and radius s K, or "(* ; q(s))" if exact (conventions 9.4 row "scaled value"). */
char * adf_scaled_get_str(size_t * len, const adf_scaled_t x);

/* ---- adf_adele: body "adele 1 <arb> <fb>" (0 or 1 occurrence). For Q the archimedean count must
   be 1; another count is ADF_DOMAIN (conventions 10.1). ---- */
int adf_adele_load_str(adf_adele_t x, const char * s, size_t len, const adf_modctx_struct * ctx,
                       const adf_text_limits_t * lim);
int adf_adele_load_str_binds(adf_adele_t x, const char * s, size_t len,
                             const adf_modctx_struct * const * binds, size_t nbinds,
                             const adf_text_limits_t * lim);
char * adf_adele_dump_str(size_t * len, const adf_adele_t x);
int adf_adele_dump_inspect(size_t * nctx, adf_ctx_desc_t * descs, const char * s, size_t len,
                           const adf_text_limits_t * lim);

/* ---- adf_cadele: body "cadele 1 <acb> <fb>" (0 or 1 occurrence) ---- */
int adf_cadele_load_str(adf_cadele_t x, const char * s, size_t len, const adf_modctx_struct * ctx,
                        const adf_text_limits_t * lim);
int adf_cadele_load_str_binds(adf_cadele_t x, const char * s, size_t len,
                              const adf_modctx_struct * const * binds, size_t nbinds,
                              const adf_text_limits_t * lim);
char * adf_cadele_dump_str(size_t * len, const adf_cadele_t x);
int adf_cadele_dump_inspect(size_t * nctx, adf_ctx_desc_t * descs, const char * s, size_t len,
                            const adf_text_limits_t * lim);

/* Layout queries of the descriptor (conventions 10.2, 12.4). Header-inline and exported. */
ADF_INLINE size_t adf_sizeof_ctx_desc(void) { return sizeof(adf_ctx_desc_t); }
ADF_INLINE size_t adf_alignof_ctx_desc(void) { return ADF_ALIGNOF(adf_ctx_desc_t); }

#ifdef __cplusplus
}
#endif

#endif /* ADELEFELD_DUMP_H */

/* adelefeld/modctx.h: modulus contexts (constructors, free, read access), context descriptors of
   dump occurrences, and the conversions of adf_fball into and out of the local backend.

   Contract: docs/conventions.md 0.4, 4.6 (lifetime and construction; closure edits E1, E2), 5.14
   (contents and constructors), 3.2 (rows "Raw context constructors", "adf_modctx_new_from_dump",
   "Exact conversion to the local backend"; closure findings C3, C5), 5.3 (local backend), 10.2
   (descriptors and inspection; closure finding C2), 12.4, 12.6, 12.10; docs/SPEC.md 10 item 4;
   docs/PLAN.md section 4 ("Contexts"); docs/proofs/policies.md section 4. Contexts are implemented
   in work package 1.8 (the scaled policy of 1.7 already uses them; docs/PLAN.md section 6).

   Rules for every constructor adf_modctx_new_* (conventions 4.6, 5.14; closure E2):
   - out is the first argument, of type adf_modctx_struct **. On ADF_OK the constructor allocates
     and fully initialises an immutable context and writes its pointer to *out. It never frees,
     mutates or reuses the context previously pointed to by *out; on success it overwrites only the
     pointer slot, and the caller must retain any previous owned pointer separately.
   - On any other status *out is untouched and no allocation is retained.
   - The caller owns the context. It frees it with adf_modctx_free only after every value that
     borrows it has been cleared or moved to another context or backend; freeing a borrowed context
     is undefined behaviour (with -DADF_CHECK_INVARIANTS it aborts, conventions 4.6).
   - Arrays passed in are copied (conventions 4.2). No operation of the library creates a context
     implicitly (conventions 4.6).
   - A context may be read by any number of threads (conventions 4.5).
   - Size (decision M1-D5): a context has at most ADF_MODCTX_MAX_BLOCKS blocks. A constructor
     whose arguments ask for more returns ADF_UNSUPPORTED, and it decides this from the arguments
     before it builds a table or allocates in proportion to them: adf_modctx_new_blocks and
     adf_modctx_new_prime_powers from k; adf_modctx_new_factorial and
     adf_modctx_new_primorial_pow from n (the number of primes up to n is above the bound as soon
     as n >= ADF_MODCTX_MAX_PRIME, the prime of index ADF_MODCTX_MAX_BLOCKS + 1). For
     adf_modctx_new_primorial_pow with e >= 2 the status for "some p^e >= 2^64" is likewise
     decided from n and e alone, by comparing n with the largest prime whose e-th power is below
     2^64, before any prime is enumerated. The order of the checks is: ADF_DOMAIN first, then
     ADF_UNSUPPORTED (conventions 3.3).

   Contents, not part of the interface (conventions 5.14): K >= 1; k >= 0 word blocks q_1..q_k,
   pairwise coprime, 2 <= q_i < 2^64, in the order supplied, with product K when k >= 1. */

#ifndef ADELEFELD_MODCTX_H
#define ADELEFELD_MODCTX_H

#include "adelefeld/common.h"
#include "adelefeld/status.h"
#include "adelefeld/fball.h"
#include "adelefeld/text.h"

/* The largest number of blocks of a context, and the prime of index ADF_MODCTX_MAX_BLOCKS + 1
   (decision M1-D5). 65536 blocks of one word are a modulus of about 4 million bits. The 65537th
   prime is 821647 (the 65536th is 821641). */
#define ADF_MODCTX_MAX_BLOCKS 65536
#define ADF_MODCTX_MAX_PRIME 821647

#ifdef __cplusplus
extern "C" {
#endif

/* ---- construction and release ---- */

/* adf_modctx_new_blocks(out, q, k): the context with the k blocks q[0..k-1], in the order supplied,
   K = their product; k = 0 gives K = 1 without blocks. Status: ADF_OK; ADF_DOMAIN if k < 0, or
   unless every q[i] >= 2 and the q[i] are pairwise coprime (conventions 5.14). q is read only
   (it may be NULL when k = 0). Cost: k^2 word gcds and the tables of
   the context. */
int adf_modctx_new_blocks(adf_modctx_struct ** out, const ulong * q, slong k);

/* adf_modctx_new_prime_powers(out, p, e, k): the context with the blocks p[i]^e[i], i = 0..k-1, in
   the order supplied; k = 0 gives K = 1 without blocks. Status: ADF_OK; ADF_DOMAIN if k < 0, if
   some p[i] is not prime (n_is_prime),
   if a prime repeats, or if some e[i] = 0; ADF_UNSUPPORTED if some p[i]^e[i] >= 2^64 (conventions
   5.14; 3.2 row "Raw context constructors"). */
int adf_modctx_new_prime_powers(adf_modctx_struct ** out, const ulong * p, const ulong * e, slong k);

/* adf_modctx_new_fmpz(out, K): the context of modulus K with one block K if 2 <= K < 2^64, and no
   block if K = 1 or K >= 2^64; a context without blocks serves only the scaled policy
   (conventions 5.14, last paragraph). Status: ADF_OK; ADF_DOMAIN if K < 1. */
int adf_modctx_new_fmpz(adf_modctx_struct ** out, const fmpz_t K);

/* adf_modctx_new_factorial(out, n): the context of modulus K = n!, with the prime powers of n! as
   blocks in increasing order of the prime (conventions 5.14, CV-21); n = 0 and n = 1 give K = 1
   without blocks. Status: ADF_OK; ADF_UNSUPPORTED if one of these prime powers is >= 2^64
   (conventions 3.2 row "Raw context constructors"; the choice between UNSUPPORTED and a context
   without blocks is recorded in docs/api-m1.md, section "Choices"). */
int adf_modctx_new_factorial(adf_modctx_struct ** out, ulong n);

/* adf_modctx_new_primorial_pow(out, n, e): the context of modulus K = (product of the primes
   p <= n)^e, with the blocks p^e in increasing order of p (conventions 5.14, "powers of a
   primorial"; PLAN section 4, "Modulus families"). n < 2 or e = 0 gives K = 1 without blocks.
   Status: ADF_OK; ADF_UNSUPPORTED if some p^e >= 2^64. */
int adf_modctx_new_primorial_pow(adf_modctx_struct ** out, ulong n, ulong e);

/* adf_modctx_new_from_dump(out, s, len, occurrence, lim): the context recorded at the
   occurrence-th context occurrence (0-based, dump traversal order) of the dump text s (conventions
   10.2; closure findings C2, C3). A "modctx" dump has exactly one occurrence. The whole dump is
   validated in the order of conventions 8.5 before the occurrence index is checked or a context
   allocated. Status: ADF_OK; ADF_PARSE, ADF_LIMIT, ADF_UNSUPPORTED, ADF_DOMAIN as a loader of the
   dump (conventions 3.2 row "adf_modctx_new_from_dump"); ADF_DOMAIN also if occurrence is not
   below the number of occurrences. The block order of the occurrence is kept. */
int adf_modctx_new_from_dump(adf_modctx_struct ** out, const char * s, size_t len, size_t occurrence,
                             const adf_text_limits_t * lim);

/* adf_modctx_free(ctx): releases a context made by a constructor. ctx = NULL does nothing
   (conventions 4.6). */
void adf_modctx_free(adf_modctx_struct * ctx);

/* ---- read access (a context is immutable; these never fail) ---- */

/* adf_modctx_get_modulus(K, ctx): K = the modulus of ctx. K is an fmpz initialised by the caller. */
void adf_modctx_get_modulus(fmpz_t K, const adf_modctx_struct * ctx);

/* adf_modctx_nblocks(ctx): the number k >= 0 of word blocks. */
slong adf_modctx_nblocks(const adf_modctx_struct * ctx);

/* adf_modctx_block(ctx, i): the block q_i, 0 <= i < k (precondition; undefined otherwise). */
ulong adf_modctx_block(const adf_modctx_struct * ctx, slong i);

/* adf_modctx_dump_str(len, ctx): the dump "adf1 Q modctx K k q_1 ... q_k" (conventions 10.1, body
   "modctx"; lower-case hexadecimal). Returned as adf_x_dump_str returns (conventions 8.1): allocated
   with flint_malloc, byte length in *len, NUL at s[len], freed with adf_str_free. */
char * adf_modctx_dump_str(size_t * len, const adf_modctx_struct * ctx);

/* ---- descriptors of context occurrences (conventions 10.2; closure finding C2) ---- */

/* One context occurrence of a dump: modulus K, block count k, blocks q[0..k-1] owned by the
   descriptor. Layout, 64-bit: K (fmpz) at 0, k (slong) at 8, q (ulong *) at 16; size 24, alignment 8
   (conventions 10.2, 12.4). The name ends in _t although the type is a plain struct, as conventions
   10.2 writes it. */
typedef struct
{
    fmpz_t K;
    slong k;
    ulong * q;
} adf_ctx_desc_t;

/* adf_ctx_desc_init(d): K = 1, k = 0, q = NULL. Never fails (conventions 10.2, closure C2). */
void adf_ctx_desc_init(adf_ctx_desc_t * d);

/* adf_ctx_desc_clear(d): releases K and the block array (conventions 10.2, closure C2). */
void adf_ctx_desc_clear(adf_ctx_desc_t * d);

/* adf_modctx_matches_desc(ctx, d): 1 if ctx has the modulus d->K and the blocks d->q[0..k-1] in
   this order, else 0. This is the match that a dump binding requires (conventions 10.2: "Every
   binding must match that occurrence's modulus and ordered blocks"). */
int adf_modctx_matches_desc(const adf_modctx_struct * ctx, const adf_ctx_desc_t * d);

/* ---- adf_fball: conversion into and out of the local backend (conventions 5.3; WP 1.8) ---- */

/* adf_fball_set_local(y, x, ctx): y = the set of x as a local value of ctx, exactly

/* Exercise the unchanged project fuzz target with its valid, smallest rational dump. */
#include "tests/fuzz/fuzz_dump.c"
