    }
    fmpz_clear(a);
    fmpz_clear(h);
    fmpz_clear(e);
    fmpz_clear(g);
    return ok;
}

/* ================================================================================================
   The grammar of conventions 10.1, one function per nonterminal, each run in the mode of the
   state. In DP_SYNTAX a failure is ADF_PARSE; in the later modes the grammar is known to hold. */

static int
dp_w_arb(dp_cur * c, dp_state * st, dp_arb * a)
{
    if (!dp_h(c, &a->m) || !dp_h(c, &a->e) || !dp_h(c, &a->rm) || !dp_h(c, &a->re))
        return dp_parse_fail(st);
    /* The bound of M1-D9 on the exponents of a qclass piece is a limit of stage 4
       (conventions 8.5 item 4), so it is decided here, on the digit strings, before any
       semantic check: dp_abs_over reads a token of any length and calls a value of more than 16
       hexadecimal digits, hence of more than 2^64, over the bound (M1-D7 is the pattern: no
       hidden bound of a machine word).  The other bodies have no such bound. */
    if (st->mode == DP_LIMITS && st->arb_exp_limit
        && (dp_abs_over(a->e, ADF_DUMP_QCLASS_EXP_MAX) || dp_abs_over(a->re, ADF_DUMP_QCLASS_EXP_MAX)))
        return dp_fail(st, ADF_LIMIT);
    return 1;
}

/* Copy a context occurrence into a descriptor, releasing its old block array (closure C2). The
   blocks are words: stage 6 has accepted the occurrence. */
static void
dp_desc_set(adf_ctx_desc_t * d, const dp_cur * c, const dp_ctx * x)
{
    size_t i, pos = x->q0;

    dp_fmpz(d->K, x->K);
    flint_free(d->q);
    d->q = NULL;
    if (x->k > 0)
    {
        d->q = (ulong *) flint_malloc(x->k * sizeof(ulong));
        for (i = 0; i < x->k; i++)
        {
            dp_span t = dp_tok_at(c->s, c->len, &pos);
            ulong v = 0;
            (void) dp_word(t, &v);
            d->q[i] = v;
        }
    }
    d->k = (slong) x->k;
}

/* ctx = h K, h k, then k blocks (conventions 10.1, line 1334). Stage 4: the block count of
   every occurrence (8.5 item 4, gate finding G8). Stage 5: at most ADF_MODCTX_MAX_BLOCKS blocks
   (decision M1-D5), decided from the count of the text alone, before the blocks are read into
   integers, before the predicate of conventions 5.14 and before any allocation in proportion
   to the count.  DP_OCC: the occurrence is counted and, if asked for, copied. Stage 6 is the
   caller's (need_blocks differs). */
static int
dp_w_ctx(dp_cur * c, dp_state * st, dp_ctx * x)
{
    size_t i;
    dp_span t;

    if (!dp_h(c, &x->K) || !dp_count(c, 1, &x->k))
        return dp_parse_fail(st);
    x->q0 = c->pos;
    for (i = 0; i < x->k; i++)
        if (!dp_h(c, &t))
            return dp_parse_fail(st);
    if (st->mode == DP_LIMITS && dp_over_items(x->k, st->lim))
        return dp_fail(st, ADF_LIMIT);
    if (st->mode == DP_WORDS && x->k > (size_t) ADF_MODCTX_MAX_BLOCKS)
        return dp_fail(st, ADF_UNSUPPORTED);
    if (st->mode == DP_OCC)
    {
        size_t o = st->nocc++;
        if (st->descs != NULL && o >= st->first && o - st->first < st->ndescs)
            dp_desc_set(&st->descs[o - st->first], c, x);
    }
    return 1;
}

/* fb = "g" A H d | "l" d ctx res_1 .. res_k (conventions 10.1, lines 1335-1336; proto _d_fb). */
static int
dp_w_fb(dp_cur * c, dp_state * st, dp_fb * f)
{
    dp_span t;
    size_t i;

    if (!dp_next(c, &t))
        return dp_parse_fail(st);
    if (dp_kw_is(t, "g"))
    {
        f->local = 0;
        if (!dp_h(c, &f->A) || !dp_h(c, &f->H) || !dp_h(c, &f->d))
            return dp_parse_fail(st);
        return 1;
    }
    if (!dp_kw_is(t, "l"))
    }
    fmpz_init(m);
    fmpz_init(e);
    arf_init(mid);
    arf_init(rad);
    arf_init(lo);
    arf_init(hi);
    dp_fmpz(m, a->m);
    dp_fmpz(e, a->e);
    arf_set_fmpz_2exp(mid, m, e);
    dp_fmpz(m, a->rm);
    dp_fmpz(e, a->re);
    arf_set_fmpz_2exp(rad, m, e);
    if (arf_sgn(mid) < 0 || arf_cmp_si(mid, 1) > 0 || !fmpz_is_one(d))
        ok = dp_fail(st, ADF_DOMAIN);
    if (ok)
    {
        int cmp;
        arf_sub(lo, mid, rad, ARF_PREC_EXACT, ARF_RND_DOWN);
        arf_add(hi, mid, rad, ARF_PREC_EXACT, ARF_RND_DOWN);
        if (keys->have)
        {
            cmp = arf_cmp(keys->lo, lo);
            if (cmp == 0)
                cmp = arf_cmp(keys->hi, hi);
            if (cmp == 0)
                cmp = fmpz_cmp(keys->H, H);
            if (cmp == 0)
                cmp = fmpz_cmp(keys->A, A);
            if (cmp >= 0)
                keys->unordered = 1;
        }
        arf_swap(keys->lo, lo);
        arf_swap(keys->hi, hi);
        fmpz_swap(keys->H, H);
        fmpz_swap(keys->A, A);
        keys->have = 1;
    }
    fmpz_clear(A);
    fmpz_clear(H);
    fmpz_clear(d);
    fmpz_clear(m);
    fmpz_clear(e);
    arf_clear(mid);
    arf_clear(rad);
    arf_clear(lo);
    arf_clear(hi);
    return ok;
}

static int
dp_w_qclass(dp_cur * c, dp_state * st)
{
    dp_span t;
    size_t n = 1, i;
    int pieces;
    dp_qkeys keys;
    int ok = 1;

    if (!dp_next(c, &t) || !(dp_kw_is(t, "lift") || dp_kw_is(t, "pieces")))
        return dp_parse_fail(st);
    pieces = dp_kw_is(t, "pieces");
    if (pieces && !dp_count(c, 8, &n))
        return dp_parse_fail(st);
    if (st->mode == DP_LIMITS && dp_over_items(n, st->lim))
        return dp_fail(st, ADF_LIMIT);
    /* The bound of M1-D9 applies to every piece of the form "pieces"; a "lift" is a single
       adele, the grammar of conventions 10.1 has no piece there, and the cost the row names
       (the range of a piece is formed, so that its end points are exact) is paid by the pieces
       only.  A lift is therefore read with its exponents as they are, as tests/ref/vectors/
       m1-dump/dump_ref.jsonl records; the reading is discussed in the lane report. */
    if (st->mode == DP_LIMITS && pieces)
        st->arb_exp_limit = 1;
    if (st->mode == DP_SEM && pieces && n == 0)
        return dp_fail(st, ADF_DOMAIN);
    arf_init(keys.lo);
    arf_init(keys.hi);
    fmpz_init(keys.H);
    fmpz_init(keys.A);
    keys.have = 0;
    keys.unordered = 0;
    for (i = 0; ok && i < n; i++)
    {
        size_t narch;
        dp_arb a[2];
        dp_fb f;
        if (!dp_w_arch(c, st, 4, &narch, a) || !dp_w_fb(c, st, &f))
            ok = 0;
        else if (st->mode == DP_SEM)
        {
            if (!pieces)
            {
                if (narch != 1 || !dp_v_arb(&a[0]) || !dp_v_fb(c, &f, NULL, NULL, NULL))
                    ok = dp_fail(st, ADF_DOMAIN);
            }
            else
                ok = dp_q_piece(c, st, narch, &a[0], &f, &keys);
        }
    }
    if (ok && st->mode == DP_SEM && keys.unordered)
        ok = dp_fail(st, ADF_DOMAIN);
    arf_clear(keys.lo);
    arf_clear(keys.hi);
    fmpz_clear(keys.H);
    fmpz_clear(keys.A);
    return ok;
}

/* The bodies without a context occurrence and without a typed loader in this file (conventions
   10.1): grammar, stage 4 and stage 5 as in proto _dump_syntax and _dump_validate; stage 6 is
   DP_NOSEM. */
static int
dp_header(const char * s, size_t len, const adf_text_limits_t * lim, size_t * body)
{
    size_t i, pos, v0, f0;

    if (len > lim->max_len)
        return ADF_LIMIT;              /* stage 1, before any byte is read */
    if (s == NULL)
        return ADF_PARSE;              /* only len = 0 is allowed with NULL (text.h) */
    /* Stage 2 (8.2): the alphabet is 0x20 to 0x7e with TAB, LF and CR.  Those three are bytes of
       the alphabet, so they pass here whatever follows; the grammar of a dump (10.1) allows no
       whitespace other than the single spaces between tokens, and the header is judged before
       the body, so a version or a field other than "1" and "Q" is ADF_UNSUPPORTED whatever the
       body holds.  Every other byte, NUL and every byte >= 0x80, is ADF_PARSE here. */
    for (i = 0; i < len; i++)
    {
        unsigned char b = (unsigned char) s[i];

        if ((b < 0x20 && b != 0x09 && b != 0x0a && b != 0x0d) || b > 0x7e)
            return ADF_PARSE;
    }
    if (len < 3 || s[0] != 'a' || s[1] != 'd' || s[2] != 'f')
        return ADF_PARSE;
    pos = v0 = 3;
    while (pos < len && s[pos] >= '0' && s[pos] <= '9')
        pos++;
    if (pos == v0 || (pos < len && s[pos] != ' '))
        return ADF_PARSE;              /* "adf" [0-9]+ ( " " | end ) */
    if (pos - v0 > 1 && s[v0] == '0')
        return ADF_PARSE;              /* a version with a leading zero */
    if (!(pos - v0 == 1 && s[v0] == '1'))
        return ADF_UNSUPPORTED;        /* another version, before the body is read */
    if (pos == len)
        return ADF_PARSE;
    pos++;
    f0 = pos;                          /* field = upper, {nonspace} */
    if (pos >= len || s[pos] < 'A' || s[pos] > 'Z')
        return ADF_PARSE;
    while (pos < len && s[pos] != ' ')
        pos++;
    if (!(pos - f0 == 1 && s[f0] == 'Q'))
        return ADF_UNSUPPORTED;
    if (pos == len)
        return ADF_PARSE;
    *body = pos + 1;
    return ADF_OK;
}

static void
dp_cur_at(dp_cur * c, const dp_parsed * P)
{
    c->s = P->s;
    c->len = P->len;
    c->pos = P->body;
    c->left = P->ntok;
}

/* Validate the whole text (stages 1 to 6). want_kind >= 0 restricts the body to that keyword
   (a typed loader: another body is not a sentence of its start symbol, ADF_PARSE, as a typed
   parser of the value form does not coerce, conventions 9.7; HEADER-FINDING: dump.h does not
   say which status a loader gives for the dump of another type). On ADF_OK
   P->node holds the spans and P->nocc the number of context occurrences. May return DP_NOSEM
   (only when want_kind < 0). */
static int
dp_validate(dp_parsed * P, const char * s, size_t len, const adf_text_limits_t * lim, int want_kind)
{
    adf_text_limits_t dflt;
    dp_state st;
    dp_cur c;
    dp_span t;
    size_t b, i;
    int kind, mode, r;

    if (lim == NULL)
    {
        adf_text_limits_default(&dflt);
        lim = &dflt;
    }
    r = dp_header(s, len, lim, &b);
    if (r != ADF_OK)
        return r;
    /* the body: tokens separated by exactly one space, none empty (proto lines 1037-1039) */
    if (b >= len || s[b] == ' ' || s[len - 1] == ' ')
        return ADF_PARSE;
    P->ntok = 1;
    for (i = b; i < len; i++)
        if (s[i] == ' ')
        {
            if (s[i + 1] == ' ')       /* i + 1 < len: s[len - 1] is not a space */
                return ADF_PARSE;
            P->ntok++;
        }
    P->s = s;
    P->len = len;
    c.s = s;
    c.len = len;
    c.pos = b;
    c.left = P->ntok;
    (void) dp_next(&c, &t);
    for (kind = 0; kind < DP_NKINDS; kind++)
        if (dp_kw_is(t, dp_kind_name[kind]))
            break;
    if (kind == DP_NKINDS || (want_kind >= 0 && kind != want_kind))
        return ADF_PARSE;
    P->body = c.pos;
    P->ntok = c.left;

/* tests/fuzz/fuzz_dump.c: the fuzzer of the dump form (src/dump.c and adf_modctx_new_from_dump
   of src/modctx.c; work package 1.4, lane m1-dump; include/adelefeld/dump.h).

   libFuzzer calls LLVMFuzzerTestOneInput with arbitrary bytes. The bytes go, without a
   terminator (a copy of exactly size bytes, so that a read past the end is caught), to the five
   inspectors, to adf_modctx_new_from_dump, and to the five loaders, each with a small fixed set of
   contexts (none, NULL, {2, 3}, {6}, K = 1 without blocks) and with one binding per occurrence
   made from the text itself by adf_modctx_new_from_dump. The address and undefined-behaviour
   sanitizers of `make fuzz` watch every read and every allocation.

   src/dump.c and src/modctx.c are included into this file, so that they are compiled with the
   sanitizers and the coverage flags of `make fuzz`; the definitions here take the place of the
   archive members dump.o and modctx.o. No FLINT load function sees the input: the loaders do not
   call one, and neither does this file.

   What is asserted (a violation aborts, and libFuzzer keeps the input as a crash):
   - every status is a loader status (conventions 3.2: OK, PARSE, LIMIT, UNSUPPORTED, DOMAIN);
   - the inspector of a type returns the status of the whole validation; the loader returns the
     same status for any binding when it is not OK; when it is OK, the loader with the bindings
     made from the text returns OK, and with a fixed context OK exactly when that context matches
     every occurrence (conventions 10.2);
   - adf_modctx_new_from_dump at occurrence i < n returns OK and a context that matches the
     descriptor of the inspector; at n it returns DOMAIN; on a text the inspector refuses it
     returns the same status (or DOMAIN where the text has no occurrence);
   - on a status other than OK the output value, *nctx, the descriptors and *out are untouched
     (conventions 4.3, closure C2);
   - on OK the value satisfies its predicate (conventions 5), and dumping it gives the input byte
     for byte (CV-38); adf_scaled_get_str gives a value text that adf_fball_set_str reads.

   The length of a printed text is read in a statement of its own, after the call that writes it
   (finding R3 of the review in docs/reviews/m1/dump/review.md: `same_bytes(adf_rat_dump_str(&tl,
   x), tl, s, n)` reads tl as an argument of the call that writes it, which the order of
   evaluation of the arguments of a call leaves open, and the seed "adf1 Q rat 1 1" then aborted
   under valgrind with an uninitialised value).

   The output of every type is zeroed with memset before its life cycle starts, so that the padding
   between the fields of the struct is defined. The initialisers of the library do not write it
   (adf_fball_init writes A, H, d, backend, mctx and res, and the struct has four padding bytes
   after backend), and the check of an untouched output compares the whole struct byte for byte.
   Without the memset that comparison reads undefined bytes: valgrind reported 120 errors from 36
   contexts for the seed, in the four types with padding, and none for rat, whose struct is an fmpq
   and has none. The check itself is kept as it is; only the bytes it reads become defined. */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "../../src/dump.c"
#include "../../src/modctx.c"

#define REQUIRE(cond) do { if (!(cond)) abort(); } while (0)

static int
loader_status(int st)
{
    return st == ADF_OK || st == ADF_PARSE || st == ADF_LIMIT || st == ADF_UNSUPPORTED || st == ADF_DOMAIN;
}

/* The fixed contexts, made once. */
static adf_modctx_struct * fx[3];
static int fx_ready = 0;

static void
fixed_contexts(void)
{
    ulong q23[2] = {2, 3}, q6 = 6;
    fmpz_t one;

    if (fx_ready)
        return;
    REQUIRE(adf_modctx_new_blocks(&fx[0], q23, 2) == ADF_OK);
    REQUIRE(adf_modctx_new_blocks(&fx[1], &q6, 1) == ADF_OK);
    fmpz_init_set_ui(one, 1);
    REQUIRE(adf_modctx_new_fmpz(&fx[2], one) == ADF_OK);
    fmpz_clear(one);
    fx_ready = 1;
}

/* Predicate L (conventions 5.3). */
static int
local_ok(const adf_fball_struct * f)
{
    fmpz_t K;
    slong i, k;
    int ok;

    if (f->mctx == NULL || f->res == NULL)
        return 0;
    k = adf_modctx_nblocks(f->mctx);
    fmpz_init(K);
    adf_modctx_get_modulus(K, f->mctx);
    ok = k >= 1 && fmpz_equal(K, f->H) && fmpz_is_zero(f->A) && fmpz_sgn(f->d) >= 1;
    for (i = 0; ok && i < k; i++)
        ok = f->res[i] < adf_modctx_block(f->mctx, i);
    fmpz_clear(K);
    return ok;
}

static int
fball_ok(const adf_fball_struct * f)
{
    return f->backend == ADF_GLOBAL ? adf_fball_is_canonical(f) : (f->backend == ADF_LOCAL && local_ok(f));
}

static void
same_bytes(const char * t, size_t tl, const char * s, size_t n)
{
    REQUIRE(t != NULL && tl == n && t[tl] == '\0' && memcmp(t, s, n) == 0);
    flint_free((void *) t);
}

enum { F_RAT, F_FBALL, F_SCALED, F_ADELE, F_CADELE };

/* Load with bindings b[0..nb-1] (or the one-context form with ctx when nb == SIZE_MAX); check the
   output against the expected status; on OK dump and compare. Returns the status. */
static int
load_one(int ty, const char * s, size_t n, const adf_text_limits_t * lim, const adf_modctx_struct * const * b,
         size_t nb, const adf_modctx_struct * ctx)
{
    int st;
    size_t tl = 0;

    switch (ty)
    {
        case F_RAT:
        {
            adf_rat_t x;
            adf_rat_struct copy;
            memset(x, 0, sizeof(*x));
            adf_rat_init(x);
            fmpq_set_si(x->q, 12345, 7);
            memcpy(&copy, x, sizeof(copy));
            st = nb == SIZE_MAX ? adf_rat_load_str(x, s, n, ctx, lim) : adf_rat_load_str_binds(x, s, n, b, nb, lim);
            if (st != ADF_OK)
                REQUIRE(memcmp(&copy, x, sizeof(copy)) == 0 && fmpz_equal_si(fmpq_numref(x->q), 12345));
            else
            {
                REQUIRE(adf_rat_is_canonical(x));
                {
                    char * t = adf_rat_dump_str(&tl, x);
                    same_bytes(t, tl, s, n);
                }
            }
            adf_rat_clear(x);
            break;
        }
        case F_FBALL:
        {
            adf_fball_t x;
            adf_fball_struct copy;
            memset(x, 0, sizeof(*x));
            adf_fball_init(x);
            fmpz_set_si(x->A, 5);
            fmpz_set_si(x->H, 18);
            memcpy(&copy, x, sizeof(copy));
            st = nb == SIZE_MAX ? adf_fball_load_str(x, s, n, ctx, lim)
                                : adf_fball_load_str_binds(x, s, n, b, nb, lim);
            if (st != ADF_OK)
                REQUIRE(memcmp(&copy, x, sizeof(copy)) == 0 && fmpz_equal_si(x->A, 5) && fmpz_equal_si(x->H, 18));
            else
            {
                REQUIRE(fball_ok(x));
                {
                    char * t = adf_fball_dump_str(&tl, x);
                    same_bytes(t, tl, s, n);
                }
            }
            adf_fball_clear(x);
            break;
        }
        case F_SCALED:
        {
            adf_scaled_t x;
            adf_scaled_struct copy;
            memset(x, 0, sizeof(*x));
            fmpq_init(x->s);
            fmpz_init(x->u);
            x->mctx = (const adf_modctx_struct *) (void *) 0x10;
            x->exact = 1;
            fmpq_set_si(x->s, -3, 5);
            memcpy(&copy, x, sizeof(copy));
            st = nb == SIZE_MAX ? adf_scaled_load_str(x, s, n, ctx, lim)
                                : adf_scaled_load_str_binds(x, s, n, b, nb, lim);
            if (st != ADF_OK)
                REQUIRE(memcmp(&copy, x, sizeof(copy)) == 0 && fmpz_equal_si(fmpq_numref(x->s), -3));
            else
            {
                fmpz_t K;
                char * v;
                adf_fball_t f;
                fmpz_init(K);
                adf_modctx_get_modulus(K, x->mctx);
                REQUIRE(fmpq_is_canonical(x->s) && (x->exact == 0 || x->exact == 1));
                if (x->exact)
                    REQUIRE(fmpz_is_zero(x->u));
                else
                    REQUIRE(fmpq_sgn(x->s) > 0 && fmpz_sgn(x->u) >= 0 && fmpz_cmp(x->u, K) < 0);
                fmpz_clear(K);
                {
                    char * t = adf_scaled_dump_str(&tl, x);
                    same_bytes(t, tl, s, n);
                }
                v = adf_scaled_get_str(&tl, x);
                adf_fball_init(f);
                REQUIRE(v != NULL && v[tl] == '\0' && adf_fball_set_str(f, v, tl, NULL) == ADF_OK);
                adf_fball_clear(f);
                flint_free(v);
            }
            fmpq_clear(x->s);
            fmpz_clear(x->u);
            break;
        }
        case F_ADELE:
        {
            adf_adele_t x;
            adf_adele_struct copy;
            memset(x, 0, sizeof(*x));
            adf_adele_init(x);
            arb_set_si(x->inf, 7);
            memcpy(&copy, x, sizeof(copy));
            st = nb == SIZE_MAX ? adf_adele_load_str(x, s, n, ctx, lim)
                                : adf_adele_load_str_binds(x, s, n, b, nb, lim);
            if (st != ADF_OK)
                REQUIRE(memcmp(&copy, x, sizeof(copy)) == 0 && arf_equal_si(arb_midref(x->inf), 7));
            else
            {
                REQUIRE(arb_is_finite(x->inf) && fball_ok(&x->fin));
                {
                    char * t = adf_adele_dump_str(&tl, x);
                    same_bytes(t, tl, s, n);
                }
            }
            adf_adele_clear(x);
            break;
        }
        default:
        {
            adf_cadele_t x;
            adf_cadele_struct copy;
            memset(x, 0, sizeof(*x));
            adf_cadele_init(x);
            acb_set_si(x->inf, 7);
            memcpy(&copy, x, sizeof(copy));
            st = nb == SIZE_MAX ? adf_cadele_load_str(x, s, n, ctx, lim)
                                : adf_cadele_load_str_binds(x, s, n, b, nb, lim);
            if (st != ADF_OK)
                REQUIRE(memcmp(&copy, x, sizeof(copy)) == 0 && arf_equal_si(arb_midref(acb_realref(x->inf)), 7));
            else
            {
                REQUIRE(acb_is_finite(x->inf) && fball_ok(&x->fin));
                {
                    char * t = adf_cadele_dump_str(&tl, x);
                    same_bytes(t, tl, s, n);
                }
            }
            adf_cadele_clear(x);
            break;
        }
    }
    REQUIRE(loader_status(st));
    return st;
}

