   Every ADF_CHECK that fails prints one line with the file, the line, the test name, the text of
   the condition and, for ADF_CHECK_MSG, the formatted message. The summary names the number of
   tests, of checks and of failures. The exit status is 1 if any check failed. */

#ifndef ADF_TEST_RUNNER_H
#define ADF_TEST_RUNNER_H

#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>

#if !defined(__GNUC__) && !defined(__clang__)
#error "the adelefeld test runner needs the constructor attribute: use GCC or Clang"
#endif

/* A helper of the runner may be unused in a given test file; that is not a warning. */

#if defined(__GNUC__) || defined(__clang__)
#define ADF_TEST_UNUSED __attribute__((unused))
#else
#define ADF_TEST_UNUSED
#endif

/* Registration list: one node per ADF_TEST. */

typedef struct adf_test
{
    const char *name;
    const char *file;
    int line;
    void (*fn)(void);
    struct adf_test *next;
} adf_test;

/* State of the run. Zero-initialised, so it is ready before the constructors run. */

static adf_test *adf_test_head ADF_TEST_UNUSED = NULL;
static adf_test *adf_test_tail ADF_TEST_UNUSED = NULL;
static unsigned long adf_test_count ADF_TEST_UNUSED = 0;
static unsigned long adf_test_checks ADF_TEST_UNUSED = 0;
static unsigned long adf_test_failures ADF_TEST_UNUSED = 0;
static unsigned long adf_test_failed_tests ADF_TEST_UNUSED = 0;
static const char *adf_test_current ADF_TEST_UNUSED = "(none)";
static unsigned long adf_test_failures_before ADF_TEST_UNUSED = 0;

/* Append to the list. Called once per test, from a constructor. */

static void ADF_TEST_UNUSED
adf_test_register(adf_test *t)
{
    t->next = NULL;
    if (adf_test_tail == NULL)
        adf_test_head = t;
    else
        adf_test_tail->next = t;
    adf_test_tail = t;
    adf_test_count++;
}

/* The common head of every failure line. Counts the check and prints where it is. */

static void ADF_TEST_UNUSED
adf_test_fail_head(const char *file, int line, const char *cond)
{
    adf_test_failures++;
    printf("FAIL %s:%d: %s: check failed: %s", file, line, adf_test_current, cond);
}

/* A failed check, without a message. */

static void ADF_TEST_UNUSED
adf_test_fail(const char *file, int line, const char *cond)
{
    adf_test_fail_head(file, line, cond);
    printf("\n");
    fflush(stdout);
}

/* A failed check with a printf message. The compiler checks the format against the arguments. */

static void ADF_TEST_UNUSED
adf_test_fail_msg(const char *file, int line, const char *cond, const char *fmt, ...)
    __attribute__((format(printf, 4, 5)));

static void
adf_test_fail_msg(const char *file, int line, const char *cond, const char *fmt, ...)
{
    va_list ap;

    adf_test_fail_head(file, line, cond);
    printf(" | ");
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    printf("\n");
    fflush(stdout);
}

#define ADF_CHECK(cond)                                                     \
    do                                                                      \
    {                                                                       \
        adf_test_checks++;                                                  \
        if (!(cond))                                                        \
            adf_test_fail(__FILE__, __LINE__, #cond);                       \
    }                                                                       \
    while (0)

/* A failed check with a message. The condition is what is named in the report. */

#define ADF_CHECK_MSG(cond, ...)                                            \
    do                                                                      \
    {                                                                       \
        adf_test_checks++;                                                  \
        if (!(cond))                                                        \
            adf_test_fail_msg(__FILE__, __LINE__, #cond, __VA_ARGS__);      \
    }                                                                       \
    while (0)

/* One test. The body follows the macro. */

#define ADF_TEST(name)                                                      \
    static void adf_test_fn_##name(void);                                   \
    static adf_test adf_test_node_##name =                                  \
        {#name, __FILE__, __LINE__, adf_test_fn_##name, NULL};              \
    static void adf_test_ctor_##name(void) __attribute__((constructor));    \
    static void                                                             \
    adf_test_ctor_##name(void)                                              \
    {                                                                       \
        adf_test_register(&adf_test_node_##name);                           \
    }                                                                       \
    static void adf_test_fn_##name(void)

#ifndef ADF_TEST_NO_MAIN

int
main(void)
{
    for (adf_test *t = adf_test_head; t != NULL; t = t->next)
    {
        adf_test_current = t->name;
        adf_test_failures_before = adf_test_failures;
        t->fn();
        if (adf_test_failures == adf_test_failures_before)
            printf("ok   %s\n", t->name);
        else
        {
            adf_test_failed_tests++;
            printf("FAIL %s (%s:%d, %lu failed checks)\n", t->name, t->file, t->line,
                   adf_test_failures - adf_test_failures_before);
        }
    }

    printf("%lu tests, %lu checks, %lu failed checks, %lu failed tests\n", adf_test_count,
           adf_test_checks, adf_test_failures, adf_test_failed_tests);
    fflush(stdout);
    return adf_test_failures == 0 ? 0 : 1;
}

#endif /* ADF_TEST_NO_MAIN */

#endif /* ADF_TEST_RUNNER_H */

/* lb = p ("x" num den v | "b" u v N) (conventions 10.1, lines 1337-1338). Stage 4: |v|, |N| at
   most max_prec (8.4); stage 5: p below 2^64 (8.5 item 5; proto _dump_validate, 1291-1298). */
static int
dp_w_lb(dp_cur * c, dp_state * st)
{
    dp_span p, f, a, b, d;

    if (!dp_h(c, &p) || !dp_next(c, &f) || !(dp_kw_is(f, "x") || dp_kw_is(f, "b"))
        || !dp_h(c, &a) || !dp_h(c, &b) || !dp_h(c, &d))
        return dp_parse_fail(st);
    if (st->mode == DP_LIMITS)
    {
        if (dp_abs_over(d, st->lim->max_prec) || (dp_kw_is(f, "b") && dp_abs_over(b, st->lim->max_prec)))
            return dp_fail(st, ADF_LIMIT);
    }
    if (st->mode == DP_WORDS && dp_over_word(p))
        return dp_fail(st, ADF_UNSUPPORTED);
    return 1;
}

/* Stage 6 of qclass (proto _dump_validate, lines 1350-1368): a lift is one adele; pieces are
   adeles with the midpoint of the real ball in [0, 1] and a finite part whose canonical triple
   has d = 1, in strictly increasing order of (mid - rad, mid + rad, H, A) (conventions 5.10,
   CV-24, CV-45).  The bound of M1-D9 on the binary exponents of the real ball of a piece is a
   limit of stage 4 and was decided in dp_w_arb before this walk, so the exact sums below are
   formed with exponents of absolute value at most ADF_DUMP_QCLASS_EXP_MAX and fit in memory
   (ARF_PREC_EXACT, arf.rst:91-107). */
typedef struct
{
    arf_t lo, hi;
    fmpz_t H, A;
    int have;
    int unordered;
} dp_qkeys;

static int
{
    size_t i, pos, v0, f0;

    if (len > lim->max_len)
        return ADF_LIMIT;              /* stage 1, before any byte is read */
    if (s == NULL)
        return ADF_PARSE;              /* only len = 0 is allowed with NULL (text.h) */
    /* Stage 2 (8.2): the alphabet is 0x20 to 0x7e with TAB, LF and CR.  Those three are bytes of
       the alphabet, so they pass here whatever follows; the grammar of a dump (10.1) allows no
       whitespace other than the single spaces between tokens, and the header is judged before
       the body, so a version or a field other than "1" and "Q" is ADF_UNSUPPORTED whatever the
       body holds.  Every other byte, NUL and every byte >= 0x80, is ADF_PARSE here. */
    for (i = 0; i < len; i++)
    {
        unsigned char b = (unsigned char) s[i];

        if (b < 0x20 || b > 0x7e)
            return ADF_PARSE;
    }
    if (len < 3 || s[0] != 'a' || s[1] != 'd' || s[2] != 'f')
        return ADF_PARSE;
    pos = v0 = 3;
    while (pos < len && s[pos] >= '0' && s[pos] <= '9')
        pos++;

    int unordered;
} dp_qkeys;

static int
dp_q_piece(const dp_cur * c, dp_state * st, size_t narch, const dp_arb * a, const dp_fb * f,
           dp_qkeys * keys)
{
    fmpz_t A, H, d, m, e, lim20;
    arf_t mid, rad, lo, hi;
    int ok = 1;

    if (narch != 1 || !dp_v_arb(a))
        return dp_fail(st, ADF_DOMAIN);
    fmpz_init(A);
    fmpz_init(H);
    fmpz_init(d);
    if (!dp_v_fb(c, f, A, H, d))
    {
        fmpz_clear(A);
        fmpz_clear(H);
        fmpz_clear(d);
        return dp_fail(st, ADF_DOMAIN);
    }
    fmpz_init(m);
    fmpz_init(e);
    fmpz_init_set_ui(lim20, UWORD(1) << 20);
    arf_init(mid);
    arf_init(rad);
    arf_init(lo);
    arf_init(hi);
    dp_fmpz(m, a->e);
    dp_fmpz(e, a->re);
    fmpz_abs(m, m);
    fmpz_abs(e, e);
    if (fmpz_cmp(m, lim20) > 0 || fmpz_cmp(e, lim20) > 0)
        ok = dp_fail(st, ADF_LIMIT);
    if (ok)
    {
        dp_fmpz(m, a->m);
        dp_fmpz(e, a->e);
        arf_set_fmpz_2exp(mid, m, e);
        dp_fmpz(m, a->rm);
        dp_fmpz(e, a->re);
        arf_set_fmpz_2exp(rad, m, e);
        if (arf_sgn(mid) < 0 || arf_cmp_si(mid, 1) > 0 || !fmpz_is_one(d))
            ok = dp_fail(st, ADF_DOMAIN);
    }
    if (ok)
    {
        int cmp;
        arf_sub(lo, mid, rad, ARF_PREC_EXACT, ARF_RND_DOWN);
        arf_add(hi, mid, rad, ARF_PREC_EXACT, ARF_RND_DOWN);
        if (keys->have)
        {
            cmp = arf_cmp(keys->lo, lo);
            if (cmp == 0)
                cmp = arf_cmp(keys->hi, hi);
            if (cmp == 0)
                cmp = fmpz_cmp(keys->H, H);

    char * t;

    if (getenv("ADF_DUMP_LIMITS_FULL") == NULL)
        return;
    /* the context of the text, and the four typed loaders bound to it */
    t = ctx_text("fball", 65536, &len, &blocks);
    ADF_CHECK_MSG(all_load(t, len, NULL, "fball", ADF_OK) == ADF_OK, "loader at the cap");
    flint_free(t);
    /* adf_modctx_new_from_dump on the modctx body of the same context */
    t = ctx_text("modctx", 65536, &len, &blocks);
    ADF_CHECK_MSG(from_dump_status(t, len, NULL, &nb) == ADF_OK, "from_dump at the cap");
    ADF_CHECK(nb == 65536);
    flint_free(t);
    /* and the scaled body, whose loader needs the same context */
    t = ctx_text("scaled", 65536, &len, &blocks);
    ADF_CHECK_MSG(all_load(t, len, NULL, "scaled", ADF_OK) == ADF_OK, "scaled loader at the cap");
    flint_free(t);
}

